import Link from 'next/link'
import { MAPS, type MapInk, type MapLabel, type PlaceId } from '@/lib/maps'

// Spelled out so Tailwind keeps the classes
const INK: Record<MapInk, string> = { land: 'map-ink-land', lake: 'map-ink-lake' }
const LABEL: Record<MapLabel['kind'], string> = {
  trail: 'map-label-trail',
  water: 'map-label-water',
  feature: 'map-label-feature',
}

// A page's map: a real place's contour lines, generated by
// scripts/meadow/maps.mjs and printed in the theme's inks through SVG masks,
// with its pins and labels on top and the map's collar beneath
export default function MapSheet({ place }: { place: PlaceId }) {
  const map = MAPS[place]
  return (
    <figure className="map-sheet">
      <div className="map-frame" style={{ aspectRatio: `${map.width} / ${map.height}` }}>
        {map.inks.map(({ ink, src }) => (
          <div
            key={ink}
            className={`map-ink ${INK[ink]}`}
            style={{ maskImage: `url(${src})`, WebkitMaskImage: `url(${src})` }}
            aria-hidden="true"
          />
        ))}
        {map.trail && (
          <svg className="map-trail" viewBox={`0 0 ${map.width} ${map.height}`} preserveAspectRatio="none" aria-hidden="true">
            <path d={map.trail} />
          </svg>
        )}
        {map.labels.map((label) => (
          <span
            key={label.text}
            className={`map-label ${LABEL[label.kind]}`}
            style={{ left: `${label.x}%`, top: `${label.y}%` }}
            aria-hidden="true"
          >
            {label.text}
          </span>
        ))}
        {map.pins.map((pin) => {
          // Near the right edge the label reads to the pin's left
          const className = `map-pin${pin.x > 60 ? ' map-pin-left' : ''}`
          const style = { left: `${pin.x}%`, top: `${pin.y}%` }
          const body = (
            <>
              <i aria-hidden="true" />
              <span>
                {pin.label}
                {pin.sub && <small>{pin.sub}</small>}
              </span>
            </>
          )
          return pin.href ? (
            <Link key={pin.label} href={pin.href} className={className} style={style}>
              {body}
            </Link>
          ) : (
            <span key={pin.label} className={className} style={style}>
              {body}
            </span>
          )
        })}
      </div>
      <figcaption className="map-collar">
        <span>
          <b>{map.name}</b> {map.region}
        </span>
        <span>{map.coords}</span>
        <span>{map.intervals}</span>
        <span>{map.credit}</span>
      </figcaption>
    </figure>
  )
}
